import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const compareIds = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const validId = id => typeof id === 'string' && id.length > 0;

// A min-heap lets newly available IDs compete with all previously queued IDs.
class IdHeap {
  items = [];

  push(id) {
    const items = this.items;
    let index = items.length;
    items.push(id);
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (items[parent] <= id) break;
      items[index] = items[parent];
      index = parent;
    }
    items[index] = id;
  }

  pop() {
    const items = this.items;
    const first = items[0];
    const last = items.pop();
    if (items.length > 0) {
      let index = 0;
      while (index * 2 + 1 < items.length) {
        let child = index * 2 + 1;
        if (child + 1 < items.length && items[child + 1] < items[child]) child++;
        if (last <= items[child]) break;
        items[index] = items[child];
        index = child;
      }
      items[index] = last;
    }
    return first;
  }
}

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Spec must be an array');
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job) ||
        !validId(job.id) || !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Invalid job fields');
    }
    if (jobs.has(job.id)) throw new Error(`Duplicate job ID: ${job.id}`);
    const deps = new Set();
    for (const dep of job.deps) {
      if (!validId(dep)) throw new Error('Invalid dependency ID');
      if (deps.has(dep)) throw new Error(`Duplicate dependency: ${dep}`);
      deps.add(dep);
    }
    jobs.set(job.id, {
      id: job.id, state: job.state, deps, children: [],
      indegree: deps.size, causes: new Set(),
    });
  }

  const available = new IdHeap();
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error(`Unknown dependency: ${dep}`);
      jobs.get(dep).children.push(job.id);
    }
    if (job.indegree === 0) available.push(job.id);
  }

  const fullOrder = [];
  while (available.items.length > 0) {
    const id = available.pop();
    const job = jobs.get(id);
    fullOrder.push(id);
    for (const childId of job.children) {
      const child = jobs.get(childId);
      // Completed states never interrupt the propagation of failed ancestry.
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(id);
      if (--child.indegree === 0) available.push(childId);
    }
  }
  if (fullOrder.length !== jobs.size) throw new Error('Dependency cycle');

  const order = [], ready = [], blocked = [];
  for (const id of fullOrder) {
    const job = jobs.get(id);
    if (job.state !== 'pending') continue;
    if (job.causes.size > 0) {
      blocked.push({ id, causes: [...job.causes].sort(compareIds) });
    } else {
      order.push(id);
      if ([...job.deps].every(dep => jobs.get(dep).state === 'succeeded')) {
        ready.push(id);
      }
    }
  }
  ready.sort(compareIds);
  blocked.sort((a, b) => compareIds(a.id, b.id));
  return { order, ready, blocked };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const plan = planJobs(JSON.parse(readFileSync(process.argv[2], 'utf8')));
    process.stdout.write(`${JSON.stringify(plan)}\n`);
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}
