import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });
const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));

test('full graph ordering precedes filtering; ready uses current states', () => {
  assert.deepEqual(planJobs([
    job('a', ['z']), job('b'), job('z', [], 'succeeded'), job('c', ['b']),
  ]), { order: ['b', 'c', 'a'], ready: ['a', 'b'], blocked: [] });
});

test('all failed ancestors survive completed intermediates and merge uniquely', () => {
  assert.deepEqual(planJobs([
    job('f', [], 'failed'), job('g', ['f'], 'failed'),
    job('s', ['g'], 'succeeded'), job('p', ['s', 'f']), job('q', ['p']),
  ]), { order: [], ready: [], blocked: [
    { id: 'p', causes: ['f', 'g'] }, { id: 'q', causes: ['f', 'g'] },
  ] });
});

test('IDs use exact code-unit ordering and input is untouched', () => {
  const ids = ['é', '😀', '\uE000', 'constructor', '__proto__', ' ', 'a', 'Z'];
  const spec = ids.map(id => Object.freeze({
    ...job(id), deps: Object.freeze([]), extra: 'ignored',
  }));
  Object.freeze(spec);
  const sorted = [...ids].sort();
  assert.deepEqual(planJobs(spec), { order: sorted, ready: sorted, blocked: [] });
});

test('malformed fields, duplicates, missing references, and all cycles fail', () => {
  const invalid = [
    null, {}, 'jobs', [null], [[]], [{}], [job('')], [job(1)],
    [job('a', null)], [job('a', 'b')], [job('a', [''])], [job('a', [1])],
    [job('a', [], 'done')], [job('a', [], null)],
    [job('a'), job('a')], [job('a', ['b', 'b']), job('b')],
    [job('a', ['missing'])], [job('a', ['a'], 'succeeded')],
    [job('a', ['b'], 'failed'), job('b', ['a'], 'succeeded')],
    [job('free'), job('a', ['b']), job('b', ['a'])],
    [job('a', new Array(1))], new Array(1),
  ];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('long dependency chains do not require recursive traversal', () => {
  const spec = Array.from({ length: 12000 }, (_, i) => job(String(i), i ? [String(i - 1)] : []));
  const result = planJobs(spec);
  assert.deepEqual(result.order, spec.map(({ id }) => id));
  assert.deepEqual(result.ready, ['0']);
});

test('CLI success, errors, and side-effect-free import', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const file = join(dir, 'spec.json');
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  const fails = args => {
    const result = run(args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    writeFileSync(file, JSON.stringify([job('雪')]));
    const result = run([file]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, '{"order":["雪"],"ready":["雪"],"blocked":[]}\n');
    fails([]);
    fails([file, file]);
    fails([join(dir, 'missing')]);
    writeFileSync(file, '{');
    fails([file]);
    writeFileSync(file, JSON.stringify([job('a', ['a'])]));
    fails([file]);
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `import ${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)}`,
    ], { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
